-- ============================================
-- 5. VERIFICACIÓN: Mostrar las traducciones insertadas
-- ============================================
SELECT 
    'TRADUCCIONES INSERTADAS PARA EVENTO 2425' as mensaje,
    cet.language_code as idioma,
    cet.name as nombre_traducido,
    cet.slug as slug_traducido,
    cet.meta_title as meta_title,
    LEFT(cet.short_description, 80) as descripcion_corta,
    LEFT(cet.meta_description, 80) as meta_descripcion
FROM cultural_events_trads cet
WHERE cet.event_id = 2425
ORDER BY cet.language_code;

